window.PORTAL_DATA = {"site":"Korijeni u kamenu i drvetu","period":"10.10.2026. – 19.11.2026.","pages":[{"slug":"dom-i-graditeljstvo","title":"Dom i graditeljstvo","sections":["sekcija-01","sekcija-02","sekcija-03","sekcija-04","sekcija-05"]},{"slug":"tkanje-i-tekstil","title":"Tkanje i tekstil","sections":["sekcija-06","sekcija-07","sekcija-08","sekcija-09","sekcija-10"]},{"slug":"predmeti-i-obicaji","title":"Predmeti i običaji","sections":["sekcija-11","sekcija-12","sekcija-13","sekcija-14"]},{"slug":"nasljedje-i-znamenitosti","title":"Nasljeđe i znamenitosti","sections":["sekcija-15","sekcija-16","sekcija-17","sekcija-18"]},{"slug":"licnosti-i-identitet","title":"Ličnosti i identitet","sections":["sekcija-19","sekcija-20","sekcija-21","sekcija-22","sekcija-23"]},{"slug":"islamska-bastina","title":"Islamska baština","sections":["sekcija-24","sekcija-25","sekcija-26","sekcija-27","sekcija-28"]}],"sections":[{"id":"sekcija-01","title":"Prva tematska cjelina: Tradicionalna bošnjačka kuća u Crnoj Gori – arhitektura kao ogledalo života","page":"dom-i-graditeljstvo","items":[{"type":"text","text":"Tradicionalna bošnjačka kuća u Crnoj Gori nastajala je kao odgovor na prirodne, društvene i kulturne okolnosti u kojima je bošnjačko stanovništvo živjelo vjekovima. Ona nije bila samo fizički prostor stanovanja, već složeni sistem značenja koji je odražavao porodične odnose, vjerske vrijednosti, društvenu hijerarhiju i ekonomske mogućnosti domaćinstva. Smještena uglavnom u planinskim i brdskim krajevima sjevera Crne Gore, ova kuća bila je prilagođena oštroj klimi, ali i potrebama višegeneracijskih porodica.","source_paragraph":1},{"type":"image","src":"assets/optimized/foto-001.webp","fallback":"assets/optimized/foto-001.webp","original":"assets/optimized/foto-001.webp","caption":"Oronula kuća Nokića u Rožajama","width":1147,"height":860,"source_paragraph":2,"index":1},{"type":"image","src":"assets/optimized/foto-002.webp","fallback":"assets/optimized/foto-002.webp","original":"assets/optimized/foto-002.webp","caption":"Vrata od Redžepagića kule u Plavu","width":933,"height":624,"source_paragraph":4,"index":2},{"type":"text","text":"Građena pretežno od kamena u prizemlju i drveta na spratovima, bošnjačka kuća simbolizovala je ravnotežu između trajnosti i topline. Kamen je pružao stabilnost i zaštitu, dok je drvo unosilo osjećaj doma, intime i fleksibilnosti. Krovovi su bili visoki, najčešće pokriveni šindrom ili kasnije crijepom, kako bi se snijeg lakše zadržavao ili klizio, u zavisnosti od terena.","source_paragraph":6},{"type":"text","text":"Unutrašnja organizacija prostora pratila je jasnu hijerarhiju. Prizemlje je često služilo kao ekonomski dio kuće – za skladištenje hrane, držanje stoke ili alata, dok je sprat bio namijenjen životu porodice. Takva podjela prostora svjedoči o racionalnom pristupu gradnji, ali i o dubokom razumijevanju prirodnog okruženja.","source_paragraph":7}],"source_paragraph":0},{"id":"sekcija-02","title":"Druga tematska cjelina: Ognjište kao simbol doma, tradicije i duhovnog kontinuiteta","page":"dom-i-graditeljstvo","items":[{"type":"text","text":"U središtu tradicionalne bošnjačke kuće nalazilo se ognjište  mjesto oko kojeg se odvijao gotovo sav porodični život. Ognjište nije bilo samo tehničko rješenje za grijanje i kuhanje, već snažan simbol doma, zajedništva i trajanja. Oko vatre su se okupljali članovi porodice, razgovaralo se, donosile su se važne odluke, a stariji su prenosili znanje i iskustvo mlađima.","source_paragraph":10},{"type":"image","src":"assets/optimized/foto-003.webp","fallback":"assets/optimized/foto-003.webp","original":"assets/optimized/foto-003.webp","caption":"","width":772,"height":767,"source_paragraph":11,"index":3},{"type":"text","text":"U zimskim večerima, kada bi snijeg prekrivao planinske krajeve, ognjište je bilo jedini izvor topline i svjetlosti. Njegova uloga tada je bila i psihološka – stvaralo je osjećaj sigurnosti i pripadnosti. Ognjište je često imalo i ritualnu dimenziju, jer se smatralo mjestom koje štiti porodicu i dom.","source_paragraph":12},{"type":"text","text":"Posebna pažnja posvećivala se održavanju ognjišta. Pepeo se nije iznosio bez potrebe, a vatra se gasila s poštovanjem. Ovi običaji govore o dubokoj vezi između čovjeka, vatre i prostora u kojem živi.","source_paragraph":13}],"source_paragraph":9},{"id":"sekcija-03","title":"Treća tematska cjelina: Čardak, divanhana i kultura gostoprimstva","page":"dom-i-graditeljstvo","items":[{"type":"text","text":"Gostoprimstvo je jedna od najvažnijih vrijednosti bošnjačke tradicije, a arhitektura kuće jasno je odražavala tu osobinu. Čardak i divanhana bili su prostori namijenjeni dočeku gostiju, razgovoru i odmoru. Smješteni na spratu ili uz glavnu prostoriju, ovi dijelovi kuće često su bili najljepše uređeni.","source_paragraph":16},{"type":"image","src":"assets/optimized/foto-004.webp","fallback":"assets/optimized/foto-004.webp","original":"assets/optimized/foto-004.webp","caption":"","width":843,"height":632,"source_paragraph":17,"index":4},{"type":"text","text":"Divanhana je bila mjesto gdje su se vodili dugi razgovori, raspravljalo o važnim pitanjima i učvršćivali društveni odnosi. Njena otvorenost prema dvorištu ili pejzažu imala je simboličku funkciju – ona je predstavljala otvorenost doma prema svijetu.","source_paragraph":18}],"source_paragraph":15},{"id":"sekcija-04","title":"Avlija i svakodnevni život porodice","page":"dom-i-graditeljstvo","items":[{"type":"text","text":"Avlija je u tradicionalnom bošnjačkom domaćinstvu predstavljala mnogo više od ograđenog dvorišnog prostora – ona je bila živo središte porodičnog života, mjesto gdje su se preplitale svakodnevne obaveze, društveni odnosi i porodična intima. Kao produžetak kuće, avlija je imala jasno definisanu funkciju u organizaciji domaćinstva, ali i duboko simboličko značenje.","source_paragraph":20},{"type":"image","src":"assets/optimized/foto-005.webp","fallback":"assets/optimized/foto-005.webp","original":"assets/optimized/foto-005.webp","caption":"Stara kuća i avlija porodice Feleć iz Rožaja","width":1141,"height":856,"source_paragraph":21,"index":5},{"type":"text","text":"U avliji su se obavljali brojni kućni poslovi: prala se odjeća, sušilo voće i povrće, pripremala zimnica, cijepalo drvo i obavljali sezonski poslovi. Ona je bila i prostor igre za djecu, ali i mjesto okupljanja porodice u toplijim danima, kada se život iz zatvorenih prostorija selio napolje. U večernjim satima, avlija je često bila mjesto razgovora, odmora i druženja, naročito tokom ljetnjih mjeseci.","source_paragraph":23},{"type":"text","text":"Zidovi koji su okruživali avliju imali su višestruku ulogu. Oni su štitili privatnost porodice, ali su istovremeno jasno razdvajali unutrašnji, porodični svijet od javnog prostora sela ili mahale. Ulazna kapija bila je simbolična tačka prelaska – ona je označavala granicu između doma i spoljašnjeg svijeta. Način na koji se ulazilo u avliju, kao i ponašanje unutar nje, bio je podložan nepisanim pravilima i običajima.","source_paragraph":24},{"type":"text","text":"Avlija je, stoga, bila prostor u kojem se ogledao porodični red, vrijednosti i odnosi među ukućanima, ali i odnos porodice prema zajednici.","source_paragraph":25}],"source_paragraph":19},{"id":"sekcija-05","title":"Graditeljsko znanje i nasljeđe bez zapisa","page":"dom-i-graditeljstvo","items":[{"type":"text","text":"Tradicionalna bošnjačka arhitektura u Crnoj Gori razvijala se bez pisanih planova, nacrta ili formalnog obrazovanja graditelja. Znanje o gradnji prenosilo se usmenim putem, sa majstora na šegrta, s koljena na koljeno. Ovo iskustveno znanje predstavljalo je spoj praktične vještine, dubokog poznavanja materijala i osjećaja za prostor.","source_paragraph":27},{"type":"image","src":"assets/optimized/foto-006.webp","fallback":"assets/optimized/foto-006.webp","original":"assets/optimized/foto-006.webp","caption":"Rekonstruisana Ganića kula u Rožajama","width":1200,"height":1600,"source_paragraph":27,"index":6},{"type":"image","src":"assets/optimized/foto-007.webp","fallback":"assets/optimized/foto-007.webp","original":"assets/optimized/foto-007.webp","caption":"Rekonstruisana Ganića kula u Rožajama-prozor","width":1200,"height":1600,"source_paragraph":30,"index":7},{"type":"text","text":"Majstori su znali kako da prilagode kuću terenu, klimi i potrebama porodice. Umjeli su da prepoznaju kvalitet kamena, da odaberu odgovarajuće drvo, da pravilno postave temelje i oblikuju prostor tako da bude funkcionalan i dugotrajan. Svaka kuća bila je jedinstvena, iako su dijelile zajedničke arhitektonske karakteristike.","source_paragraph":33},{"type":"image","src":"assets/optimized/foto-008.webp","fallback":"assets/optimized/foto-008.webp","original":"assets/optimized/foto-008.webp","caption":"Rekonstruisana Ganića kula u Rožajama-ulazna vrata","width":1200,"height":1600,"source_paragraph":34,"index":8},{"type":"text","text":"Ovo graditeljsko znanje danas se prepoznaje kao važan dio nematerijalne kulturne baštine. Njegovim nestajanjem gubi se ne samo specifičan način gradnje, već i čitav sistem vrijednosti i odnosa prema prostoru. Digitalno dokumentovanje i istraživanje ovih praksi predstavlja pokušaj da se ovo znanje sačuva od zaborava.","source_paragraph":36}],"source_paragraph":26},{"id":"sekcija-06","title":"Tkanje kao dio ženskog identiteta","page":"tkanje-i-tekstil","items":[{"type":"text","text":"Tkanje i vez zauzimali su centralno mjesto u životu bošnjačkih žena. Ove vještine bile su dio svakodnevice, ali i važan element ličnog i porodičnog identiteta. Kroz tekstilni rad, žene su doprinosile ekonomiji domaćinstva, ali su istovremeno izražavale kreativnost i estetski osjećaj.","source_paragraph":39},{"type":"image","src":"assets/optimized/foto-009.webp","fallback":"assets/optimized/foto-009.webp","original":"assets/optimized/foto-009.webp","caption":"Ćilim ručni rad-masina za pletenje","width":976,"height":732,"source_paragraph":40,"index":9},{"type":"text","text":"Od najranijeg uzrasta djevojčice su učile osnove predenja, tkanja i veza. Znanje se prenosilo u okviru porodice, a kvalitet i bogatstvo tekstilnih predmeta često su bili pokazatelj marljivosti i umijeća žene. Tkanine su se koristile za odjeću, posteljinu, prostirke i dekorativne elemente doma.","source_paragraph":42},{"type":"image","src":"assets/optimized/foto-010.webp","fallback":"assets/optimized/foto-010.webp","original":"assets/optimized/foto-010.webp","caption":"Ručni rad bošnjakinja","width":1429,"height":953,"source_paragraph":43,"index":10},{"type":"text","text":"Tekstilni rad bio je i prostor ženskog zajedništva – žene su se okupljale, razmjenjivale iskustva i motive, prenoseći ne samo tehniku, već i priče, običaje i životna iskustva.","source_paragraph":45}],"source_paragraph":38},{"id":"sekcija-07","title":"Simbolika motiva u bošnjačkom vezu","page":"tkanje-i-tekstil","items":[{"type":"text","text":"Bošnjački vez predstavlja bogat vizuelni jezik ispunjen simbolikom. Motivi koji su se pojavljivali na tkaninama nisu bili nasumični – svaki oblik, linija i boja imali su svoje značenje. Cvjetni motivi simbolizovali su život i obnovu, geometrijski oblici red i ravnotežu, dok su pojedini znakovi imali zaštitnu ulogu.","source_paragraph":48},{"type":"image","src":"assets/optimized/foto-011.webp","fallback":"assets/optimized/foto-011.webp","original":"assets/optimized/foto-011.webp","caption":"Simbolika motiva","width":490,"height":861,"source_paragraph":49,"index":11},{"type":"text","text":"Vez je često bio povezan s vjerom i duhovnošću. Određeni motivi korišćeni su u posebnim prilikama, poput svadbi ili vjerskih praznika. Kroz ove ornamente, žene su prenosile poruke, emocije i želje, ostavljajući lični pečat na svakom predmetu.","source_paragraph":51}],"source_paragraph":47},{"id":"sekcija-08","title":"Prirodni materijali i tehnike izrade","page":"tkanje-i-tekstil","items":[{"type":"text","text":"Tradicionalna tekstilna proizvodnja u bošnjačkim krajevima Crne Gore temeljila se gotovo isključivo na prirodnim materijalima i ručnom radu, što je ovu praksu činilo sporom, zahtjevnom, ali i izuzetno vrijednom. Vuna, lan i pamuk bili su osnovni sirovinski resursi, a njihova obrada podrazumijevala je višefazni proces koji je zahtijevao veliko iskustvo, preciznost i strpljenje.","source_paragraph":54},{"type":"image","src":"assets/optimized/foto-012.webp","fallback":"assets/optimized/foto-012.webp","original":"assets/optimized/foto-012.webp","caption":"Bošnjačka marama od prirodnog materijala","width":882,"height":588,"source_paragraph":55,"index":12},{"type":"text","text":"Vuna, kao najzastupljeniji materijal, dobijala se šišanjem ovaca, najčešće u proljećnim mjesecima. Nakon šišanja, vuna se prala, sušila i raščešljavala pomoću grebenova, a zatim prela na preslici ili vretenu. Ovaj proces bio je dugotrajan i fizički zahtjevan, ali je omogućavao dobijanje prediva različite debljine, u zavisnosti od namjene tkanine. Lan i pamuk zahtijevali su dodatne faze obrade, uključujući močenje, lomljenje i češljanje vlakana, prije samog predenja.","source_paragraph":57},{"type":"text","text":"Tkanje se obavljalo na drvenim razbojima, koji su često bili smješteni u posebnim prostorijama kuće ili u avliji. Razboj je predstavljao složen mehanizam koji je zahtijevao tehničko znanje i vještinu rukovanja. Svaki pokret imao je svoju funkciju, a ritam tkanja bio je rezultat dugogodišnje prakse. Upravo u tom ritmu ogledala se veza između žene, materijala i prostora.","source_paragraph":58},{"type":"text","text":"Posebno važan segment tekstilne proizvodnje bilo je bojenje prediva. Boje su dobijane iz prirodnih izvora – biljaka poput broća, luka, koprive i orahove kore, ali i iz zemlje i mineralnih pigmenata. Proces bojenja zahtijevao je precizno poznavanje prirode, godišnjih doba i hemijskih reakcija. Rezultat su bile tkanine toplih, postojanih nijansi koje su odolijevale vremenu i upotrebi.","source_paragraph":59},{"type":"text","text":"Ove tehnike danas predstavljaju dragocjeno svjedočanstvo o znanju i samoodrživosti tradicionalnih zajednica, ali i o dubokoj povezanosti čovjeka i prirode.","source_paragraph":60}],"source_paragraph":53},{"id":"sekcija-09","title":"Tekstil u obredima i važnim životnim trenucima","page":"tkanje-i-tekstil","items":[{"type":"text","text":"Tekstilni predmeti imali su posebno mjesto u svim ključnim momentima ljudskog života, od rođenja do smrti. U tradicionalnoj bošnjačkoj kulturi, tkanine nisu bile samo funkcionalni predmeti, već snažni simboli koji su pratili čovjeka kroz najvažnije životne prijelaze.","source_paragraph":63},{"type":"text","text":"Prilikom rođenja djeteta, korišćene su posebne tkanine za povijanje, često izrađene od prirodnih materijala i jednostavnih motiva. Vjerovalo se da određeni uzorci i boje imaju zaštitnu moć, te da štite dijete od bolesti i zlih uticaja. Ovi predmeti često su čuvani i kasnije, kao uspomena ili amajlija.","source_paragraph":64},{"type":"image","src":"assets/optimized/foto-013.webp","fallback":"assets/optimized/foto-013.webp","original":"assets/optimized/foto-013.webp","caption":"Detalji anterije","width":757,"height":1136,"source_paragraph":65,"index":13},{"type":"text","text":"Svadbeni običaji posebno su obilovali tekstilnim elementima. Vezeni peškiri, marame, prostirke i prekrivači imali su ceremonijalnu ulogu i predstavljali su dio miraza. Bogatstvo veza i kvalitet izrade svjedočili su o umijeću mlade, ali i o ugledu njene porodice. Tekstil je bio prisutan u svakom segmentu svadbenog rituala – od ukrašavanja prostora do simboličnih darova.","source_paragraph":67},{"type":"text","text":"U vjerskim praznicima, tekstil je doprinosio svečanosti doma i zajednice. Posebni stolnjaci, peškiri i zavjese korišćeni su samo u tim prilikama, naglašavajući svetost i značaj trenutka. Na taj način, tekstil je postajao medij kroz koji se izražavala vjera, poštovanje tradicije i osjećaj pripadnosti.","source_paragraph":68}],"source_paragraph":62},{"id":"sekcija-10","title":"Očuvanje tekstilne baštine danas","page":"tkanje-i-tekstil","items":[{"type":"text","text":"U savremenom kontekstu, tradicionalne tkanine i vez sve više nestaju iz svakodnevne upotrebe. Industrijska proizvodnja, promjena načina života i gubitak praktične potrebe doveli su do toga da se ovi predmeti danas najčešće nalaze u sanducima, privatnim zbirkama ili zaboravljenim prostorima domaćinstava.","source_paragraph":73},{"type":"image","src":"assets/optimized/foto-014.webp","fallback":"assets/optimized/foto-014.webp","original":"assets/optimized/foto-014.webp","caption":"Ćilim granaš","width":1207,"height":906,"source_paragraph":74,"index":14},{"type":"text","text":"Očuvanje tekstilne baštine zahtijeva sistematski i interdisciplinarni pristup. Pored fizičke zaštite i restauracije, neophodno je dokumentovati tehnike izrade, simboliku motiva i lične priče vezane za pojedine predmete. Digitalizacija predstavlja jedan od najefikasnijih načina da se ova baština sačuva i učini dostupnom široj javnosti.","source_paragraph":76},{"type":"text","text":"Kroz digitalne platforme, tradicionalni tekstil dobija novu vidljivost i postaje obrazovni resurs, ali i inspiracija savremenim umjetnicima i istraživačima. Na taj način, tekstilna baština ne ostaje zatvorena u prošlosti, već postaje aktivni dio kulturnog identiteta.","source_paragraph":77}],"source_paragraph":72},{"id":"sekcija-11","title":"Starinsko posuđe kao dio porodične istorije","page":"predmeti-i-obicaji","items":[{"type":"text","text":"Starinsko posuđe u bošnjačkim domaćinstvima bilo je neizostavan dio svakodnevnog života, ali i važan nosilac porodičnog sjećanja. Džezve, sahani, tepsije, lonci i činije korišćeni su svakodnevno, ali su istovremeno imali i simboličku vrijednost.","source_paragraph":80},{"type":"image","src":"assets/optimized/foto-015.webp","fallback":"assets/optimized/foto-015.webp","original":"assets/optimized/foto-015.webp","caption":"Stara džezva u Zavićajnom muzeju u Rožajama","width":761,"height":1141,"source_paragraph":81,"index":15},{"type":"image","src":"assets/optimized/foto-016.webp","fallback":"assets/optimized/foto-016.webp","original":"assets/optimized/foto-016.webp","caption":"Stari fildžan Zavićajnom muzeju u Rožajama","width":951,"height":634,"source_paragraph":86,"index":16},{"type":"image","src":"assets/optimized/foto-017.webp","fallback":"assets/optimized/foto-017.webp","original":"assets/optimized/foto-017.webp","caption":"Tabija u Zavičajnom muzeju u Rožajama","width":1033,"height":689,"source_paragraph":90,"index":17},{"type":"text","text":"Ovi predmeti često su se prenosili s generacije na generaciju, čime su postajali dio porodičnog nasljeđa. Tragovi upotrebe – ogrebotine, patina, deformacije – svjedočili su o dugom životu predmeta i brojnim generacijama koje su ih koristile. U tom smislu, posuđe je postajalo svojevrsni arhiv porodične istorije‚","source_paragraph":92}],"source_paragraph":79},{"id":"sekcija-12","title":"Bakar i zemlja – materijali tradicije","page":"predmeti-i-obicaji","items":[{"type":"text","text":"Bakreno i zemljano posuđe predstavljalo je temelj materijalne kulture tradicionalnih bošnjačkih domaćinstava u Crnoj Gori, ali i širem balkanskom prostoru. Ovi materijali nisu birani slučajno – njihova upotreba rezultat je dugotrajnog iskustva, dostupnosti sirovina, ali i razvijenih zanatskih praksi koje su se prenosile generacijama.","source_paragraph":95},{"type":"image","src":"assets/optimized/foto-018.webp","fallback":"assets/optimized/foto-018.webp","original":"assets/optimized/foto-018.webp","caption":"Bakarni Ibrik u Zavičajnom muzeju u Rožajama","width":714,"height":964,"source_paragraph":97,"index":18},{"type":"text","text":"Bakar je bio jedan od najcjenjenijih materijala u domaćinstvu, prvenstveno zbog svojih fizičkih svojstava. Njegova sposobnost ravnomjernog provođenja toplote činila ga je idealnim za pripremu hrane, naročito jela koja su zahtijevala dugotrajno kuvanje. Džezve, lonci, tepsije i ibrici izrađeni od bakra bili su neizostavni dio kuhinje, ali su istovremeno predstavljali i znak domaćinske urednosti i ugleda porodice.","source_paragraph":99},{"type":"image","src":"assets/optimized/foto-019.webp","fallback":"assets/optimized/foto-019.webp","original":"assets/optimized/foto-019.webp","caption":"Stara slika iz arhive Halila Markisica bakarni Ibrik","width":1021,"height":688,"source_paragraph":100,"index":19},{"type":"text","text":"Estetska dimenzija bakrenog posuđa bila je jednako važna kao i njegova funkcionalnost. Mnogi predmeti bili su ukrašeni jednostavnim ornamentima, geometrijskim linijama ili biljnim motivima, često graviranim ručno. Ovi ukrasi nisu imali samo dekorativnu ulogu, već su svjedočili o vještini majstora, ali i o kulturnim uticajima koji su se preplitalli kroz trgovačke i društvene veze.","source_paragraph":102},{"type":"text","text":"Zemljano posuđe, izrađeno od lokalne gline, bilo je dostupnije i masovnije korišćeno. Njegova proizvodnja vezana je za lokalne grnčarske centre, a predmeti poput ćupova, lonaca i testija koristili su se za čuvanje vode, mlijeka, žitarica i drugih namirnica. Zemljano posuđe imalo je posebnu vrijednost u očuvanju hrane, jer je omogućavalo prirodnu regulaciju temperature i vlažnosti.","source_paragraph":103},{"type":"text","text":"Upotreba bakra i zemlje svjedoči o snažnoj povezanosti tradicionalnog domaćinstva sa prirodnim resursima, ali i o razvijenim trgovačkim mrežama koje su omogućavale nabavku sirovina i razmjenu gotovih proizvoda. Ovi predmeti danas predstavljaju dragocjene artefakte materijalne kulture i važan izvor za proučavanje svakodnevnog života i ekonomskih odnosa prošlih vremena.","source_paragraph":104}],"source_paragraph":94},{"id":"sekcija-13","title":"Sinija kao centar porodičnog okupljanja","page":"predmeti-i-obicaji","items":[{"type":"text","text":"Sinija je zauzimala centralno mjesto u organizaciji porodičnog života i svakodnevnih rituala ishrane u tradicionalnom bošnjačkom domaćinstvu. Kao niski, okrugli sto, sinija nije bila samo funkcionalni predmet, već simbol zajedništva, jednakosti i porodične kohezije.","source_paragraph":110},{"type":"image","src":"assets/optimized/foto-020.webp","fallback":"assets/optimized/foto-020.webp","original":"assets/optimized/foto-020.webp","caption":"Sinija-Sofra","width":698,"height":523,"source_paragraph":111,"index":20},{"type":"text","text":"Obrok oko sinije bio je društveni čin, strogo uređen nepisanim pravilima ponašanja. Članovi porodice sjedjeli su na podu ili niskim sećijama, bez izražene hijerarhije, čime se naglašavala ideja zajedništva i međusobnog poštovanja. Dijeljenje hrane iz zajedničkih posuda imalo je snažnu simboliku – ono je učvršćivalo porodične veze i osjećaj pripadnosti.","source_paragraph":113},{"type":"text","text":"Način na koji se sjedjelo, jelo i razgovaralo oko sinije bio je dio procesa socijalizacije mlađih članova porodice. Djeca su kroz svakodnevne obroke učila osnovne društvene vrijednosti: strpljenje, umjerenost, poštovanje starijih i solidarnost. Sinija je, stoga, bila i prostor neformalne edukacije.","source_paragraph":114},{"type":"text","text":"U širem kulturnom kontekstu, sinija predstavlja važan element nematerijalne baštine, jer je vezana za rituale, običaje i svakodnevne prakse koje oblikuju identitet zajednice. Njena simbolika prevazilazi puku funkcionalnost, čineći je jednim od ključnih elemenata tradicionalnog doma.","source_paragraph":115}],"source_paragraph":109},{"id":"sekcija-14","title":"Predmeti koji prate čovjeka od rođenja do smrti","page":"predmeti-i-obicaji","items":[{"type":"text","text":"Materijalna kultura tradicionalnog bošnjačkog društva bila je usko povezana sa životnim ciklusom pojedinca. Predmeti koji su pratili čovjeka od rođenja do smrti imali su jasno definisane funkcije, ali i duboku simboličku i ritualnu vrijednost.","source_paragraph":121},{"type":"image","src":"assets/optimized/foto-021.webp","fallback":"assets/optimized/foto-021.webp","original":"assets/optimized/foto-021.webp","caption":"Bešik u centru sobe – sluzio za uspavljivanje male djece","width":1199,"height":799,"source_paragraph":123,"index":21},{"type":"text","text":"Kolijevke, izrađene od drveta i često jednostavno ukrašene, simbolizovale su početak života i brigu zajednice za novi život. Njihova izrada i upotreba bili su praćeni određenim običajima i vjerovanjima, koji su imali za cilj zaštitu djeteta.","source_paragraph":125},{"type":"text","text":"Sanduci, naročito oni vezani za miraz, predstavljali su simbol porodičnog kontinuiteta i društvenog statusa. U njima su se čuvali tekstil, odjeća i dragocjenosti, ali i porodične uspomene. Sanduk je često pratio ženu kroz cio život, postajući lični i porodični arhiv.","source_paragraph":126},{"type":"text","text":"Predmeti vezani za smrt i sjećanje imali su posebnu ritualnu funkciju. Oni su pomagali zajednici da se oprosti od preminulog i očuva uspomena na njega. Ovi predmeti svjedoče o odnosu prema prolaznosti, smrti i kolektivnom pamćenju.","source_paragraph":127}],"source_paragraph":120},{"id":"sekcija-15","title":"Digitalno očuvanje bošnjačke baštine","page":"nasljedje-i-znamenitosti","items":[{"type":"text","text":"U savremenom društvu, očuvanje kulturne baštine suočava se sa brojnim izazovima, među kojima su urbanizacija, migracije i gubitak tradicionalnih znanja. Digitalno očuvanje predstavlja jedan od najefikasnijih načina da se materijalna i nematerijalna baština dokumentuje, zaštiti i učini dostupnom široj javnosti.","source_paragraph":134},{"type":"image","src":"assets/optimized/foto-022.webp","fallback":"assets/optimized/foto-022.webp","original":"assets/optimized/foto-022.webp","caption":"Kreirao naslovnicu – Admir Đozović","width":914,"height":514,"source_paragraph":135,"index":22},{"type":"text","text":"Digitalna platforma projekta „Korijeni u kamenu i drvetu“ omogućava sistematsko prikupljanje, obradu i prezentaciju kulturnih dobara bošnjačke zajednice u Crnoj Gori. Kroz digitalizaciju predmeta, fotografija, terenskih zapisa i usmenih svjedočanstava, stvara se trajna arhiva koja prevazilazi prostorna i vremenska ograničenja.","source_paragraph":137},{"type":"text","text":"Ovakav pristup ne samo da doprinosi očuvanju baštine, već i njenoj reinterpretaciji u savremenom kontekstu. Digitalni sadržaji postaju obrazovni resurs, istraživačka baza i sredstvo jačanja kulturnog identiteta, posebno među mlađim generacijama. Na taj način, bošnjačka kulturna baština dobija aktivnu ulogu u savremenom društvu, umjesto da ostane zatvorena u prošlosti.","source_paragraph":138}],"source_paragraph":133},{"id":"sekcija-16","title":"Džamija Mali Ostros-Bar","page":"nasljedje-i-znamenitosti","items":[{"type":"image","src":"assets/optimized/foto-023.webp","fallback":"assets/optimized/foto-023.webp","original":"assets/optimized/foto-023.webp","caption":"","width":1800,"height":1278,"source_paragraph":145,"index":23},{"type":"text","text":"Džamija je izgrađena 1844. godine. U više navrata je sanirana. Nakon katastrofalnog zemljotresa izvršena je temeljna sanacija 1984. godine, sredstvima i radnim akcijama mještana, kao i finansijskom pomoći Starješinstva Islamske zajednice Crne Gore. Džamija je građena od tvrdog materijala. Djelimično je sanirana i 2014. godine sredstvima dijaspore iz ovog kraja. U haremu se nalazi staro mezarje, koje datira još iz osmanskog perioda sa raznim uzglavnim nišanima sa natpisima na osmanskom pismu. U haremu džamije, ispred samog ulaza, nalazi se stari bunar (bistijerna) na kojem je uklesana godina 1310. H. što odgovara 1892. godini. Džamija ima abdesthanu i mekteb. U dvorištu džamije, 1987. godine, podignuto je turbe šejhu Tahiru Kanaćeviću, poznatom imamu ove džamije.","source_paragraph":146},{"type":"image","src":"assets/optimized/foto-024.webp","fallback":"assets/optimized/foto-024.webp","original":"assets/optimized/foto-024.webp","caption":"","width":1800,"height":2082,"source_paragraph":147,"index":24}],"source_paragraph":144},{"id":"sekcija-17","title":"Džamija Gornji Murići-Bar","page":"nasljedje-i-znamenitosti","items":[{"type":"image","src":"assets/optimized/foto-025.webp","fallback":"assets/optimized/foto-025.webp","original":"assets/optimized/foto-025.webp","caption":"","width":1800,"height":1242,"source_paragraph":151,"index":25},{"type":"text","text":"Prema određenim izvorima, džamija je izgrađena 1602. godine. U više navrata je sanirana, a najobimnija sanacija izvršena je 1984. godine nakon oštećenja od zemljotresa 1979. godine. Izgrađena je od tvrdog materijala, prilozima mještana i sredstvima Starješinstva Islamske zajednice Crne Gore. Na podnožju munare nalazi se mermerna ploča na kojoj je uklesano da je sanaciju munare finansirao Hadžija Muratović 1988. godine. Džamija je sređena i renovirana i 2018., međutim, u ovom selu više nema ni jedno domaćinstvo pa se u njoj ne obavljaju namazi, izuzev jedne teravije tokom ramazana. U haremu se nalazi obnovljeni mekteb i veliko mezarje sa starim nišanima na kojima su natpisi na osmanskom pismu.","source_paragraph":152},{"type":"image","src":"assets/optimized/foto-026.webp","fallback":"assets/optimized/foto-026.webp","original":"assets/optimized/foto-026.webp","caption":"","width":1800,"height":1955,"source_paragraph":153,"index":26}],"source_paragraph":150},{"id":"sekcija-18","title":"IC Nova džamija u Ostrosu-Bar","page":"nasljedje-i-znamenitosti","items":[{"type":"image","src":"assets/optimized/foto-027.webp","fallback":"assets/optimized/foto-027.webp","original":"assets/optimized/foto-027.webp","caption":"","width":1800,"height":1552,"source_paragraph":155,"index":27},{"type":"text","text":"Nova džamija u Ostrosu, odnosno Islamski centar nalazi se u samom središtu Ostrosa, kojem gravitiraju sela Krajine. Izgrađena je sredstvima dijaspore, pri čemu je porodica Avdulja Peraševića finansirala radove na munari, a Turska agencija za međunarodnu saradnju i koordinaciju (TIKA) finansirala je završne radove na objektu i enterijer. Islamski centar je otvoren 2019. godine. Riječ je o multifunkcionalnoj zgradi na tri nivoa sa visokom munarom sa dva šerefeta. U prizemlju se nalazi abdesthana, gasulhana sa musafirhanom, kuhinja, kancelarije, biblioteka i garaža. Na drugom nivou je mesdžidski prostor unutrašnje površine 114 m2., a na gornjem spratu nalazi se velika sala, kapaciteta 150 gostiju, u kojoj se održavaju predavanja i iftarska okupljanja. U džamiji se klanjaju svi dnevni namazi, ali zbog seoskih džamija u njoj se ne klanja džuma namaz. U zgradi je sjedište Medžlisa Islamske zajednice Ostros.","source_paragraph":156},{"type":"image","src":"assets/optimized/foto-028.webp","fallback":"assets/optimized/foto-028.webp","original":"assets/optimized/foto-028.webp","caption":"","width":1800,"height":950,"source_paragraph":157,"index":28}],"source_paragraph":154},{"id":"sekcija-19","title":"AVDO MEĐEDOVIĆ","page":"licnosti-i-identitet","items":[{"type":"text","text":"Avdo Međedović je rođen 1875. godine u selu Obrov kod Bijelog Polja, u Sandžaku.","source_paragraph":160},{"type":"text","text":"Najpoznatiji je bošnjački epski pjesnik i guslar.","source_paragraph":161},{"type":"text","text":"Njegova epska pjesma ‘’Ženidba Smailagić Meha’’ ima 12.311 stihova i duga je kao Ilijada","source_paragraph":162},{"type":"text","text":"i Odiseja. Američki naučnik Milman Peri, istraživač i profesor sa Univerziteta Harvard","source_paragraph":163},{"type":"text","text":"iz prve polovine 20. vijeka, nazvao ga je „jugoslovenskim","source_paragraph":164},{"type":"text","text":"Homerom”. U djetinjstvu nije pohađao nikakvu školu, a nakon navršenog punoljetstva devet","source_paragraph":165},{"type":"text","text":"godina je služio u osmanskoj vojsci i za to vrijeme dobro savladao osmansko-turski jezik i","source_paragraph":166},{"type":"text","text":"u Solunu završio podoficirsku školu. Avdo je bio musliman tihe naravi ali razvijenih vjerskih","source_paragraph":167},{"type":"text","text":"i moralnih osjećanja, što se najbolje vidi iz činjenice da je kao vojnik svega jednom bio","source_paragraph":168},{"type":"text","text":"kažnjen kada mu je jedan Anadolac opsovao din (vjeru) zbog čega ga je Avdo, ogorčen","source_paragraph":169},{"type":"text","text":"vjerskom mlitavošću anadolijskih Turaka koje je nazivao “nevjernicima” udario kundakom.","source_paragraph":170},{"type":"text","text":"Poslije povratka iz vojske životni vijek je proveo na imanju u rodnom Obrovu, radeći","source_paragraph":171},{"type":"text","text":"u porodičnoj radnji - kasapnici u Bijelom Polju. Guslarsku vještinu je učio prvo od oca Huseina,","source_paragraph":172},{"type":"text","text":"a kasnije i od drugih čuvenih guslara toga vremena: Ćor-Husa Husovića i drugih.","source_paragraph":173},{"type":"text","text":"Zahvaljujući talentu i vještini, tokom vremena je postao poznatiji guslar i narodni pjevač u","source_paragraph":174},{"type":"text","text":"kraju.","source_paragraph":175},{"type":"text","text":"Milman Peri je zabilježio tokom 1935. godine, na specijalnim aluminijumskim","source_paragraph":176},{"type":"text","text":"fonografskim pločama, 80.000 Avdovih epskih stihova. Na osnovu tih istraživanja","source_paragraph":177},{"type":"text","text":"profesor Peri je zasnovao modernu teoriju usmene književnosti i modernu homerologiju.","source_paragraph":178},{"type":"text","text":"Nastavljač Perijevog rada na sakupljanju epskog stvaralaštva Albert Bates Lord, također","source_paragraph":179},{"type":"text","text":"profesor na Harvardu, 1950/51, zabilježio","source_paragraph":180},{"type":"text","text":"je još 18.000 Međedovićevih stihova, kompletirajući na taj način impozantnu kolekciju","source_paragraph":181},{"type":"text","text":"od oko 100.000 stihova „sandžačkog Homera” Avda Međedovića.","source_paragraph":182},{"type":"text","text":"Repertoar Avda Međedovića sadrži 58 pjesama, a najviše ih je zabilježio Perijev pomoćnik","source_paragraph":183},{"type":"text","text":"Nikola Vujinović. Ukupan broj stihova je 44902 koji su snimljeni na pločama i 33653","source_paragraph":184},{"type":"text","text":"koji su zabilježeni diktiranjem, prema Lordovim bilješkama.","source_paragraph":185},{"type":"text","text":"Bošnjački Milman Parry, profesor Harvardskog univerziteta dr Zlatan Čolaković,","source_paragraph":186},{"type":"text","text":"inače sin velikog bošnjačkog književnika Envera Čolakovića, autora poznatog romana","source_paragraph":187},{"type":"text","text":"„Legenda o Ali-paši“ transkribovao je sa zvučnih snimaka više od 80.000 stihova","source_paragraph":188},{"type":"text","text":"bošnjačke epike harvardskog Perijevog arhiva. Avdo Međedović je umro 1953. godine","source_paragraph":189},{"type":"text","text":"potpuno nepoznat i nepriznat u svom vremenu i u svom narodu. Bošnjaci su prvi put","source_paragraph":190},{"type":"text","text":"objavili njegovu “Ženidbu Smailagić Meha” 1987. godine.","source_paragraph":191},{"type":"image","src":"assets/optimized/foto-029.webp","fallback":"assets/optimized/foto-029.webp","original":"assets/optimized/foto-029.webp","caption":"Bista Avda Međedovića u B. Polju, foto:","width":1800,"height":1350,"source_paragraph":194,"index":29}],"source_paragraph":159},{"id":"sekcija-20","title":"Bošnjačka gradska kuća","page":"licnosti-i-identitet","items":[{"type":"text","text":"Bošnjačke gradske kuće u Crnoj Gori građene su prepoznatljivim arhitektonskim stilom koji je objedinjavao funkcionalnost, tradiciju i vjerski svjetonazor. Najčešće su imale dva sprata, pri čemu je prizemlje građeno od kamena, dok je sprat bio podizan od drvenih brvana ili u tehnici čatme. Krovovi su pokrivani šindrom, što je bilo karakteristično za gradnju tog vremena i prostora.","source_paragraph":197},{"type":"text","text":"Jedna od osnovnih odlika ovih kuća bila je postojanje posebnih prostorija namijenjenih prijemu gostiju. U okviru kuće nalazile su se divanhane, uređene slično musafirskim sobama, ali sa dodatnim arhitektonskim elementom – ćoškom, odnosno isturenim dijelom kuće nalik balkonu, koji je bio nadnesen nad avlijom ili sokakom. Ovaj prostor omogućavao je pogled na dvorište i ulicu, ali je istovremeno čuvao privatnost doma.","source_paragraph":198},{"type":"text","text":"Nažalost, danas je samo mali broj ovakvih kuća sačuvan. Mogu se pronaći u Rožajama, Plavu, Gusinju, Pljevljima i Staroj Varoši u Podgorici, dok su u drugim gradovima očuvani tek pojedinačni primjeri. Prepuštene zubu vremena i bez adekvatne zaštite, stare bošnjačke kuće jedinstvene arhitekture nestaju pred našim očima.","source_paragraph":199},{"type":"image","src":"assets/optimized/foto-030.webp","fallback":"assets/optimized/foto-030.webp","original":"assets/optimized/foto-030.webp","caption":"Stara kuća Feleća koja je devastirana","width":552,"height":414,"source_paragraph":200,"index":30},{"type":"text","text":"Prilikom izgradnje kuće, Bošnjaci su, u skladu s mogućnostima i konfiguracijom terena, nastojali da objekat orijentišu prema jugoistočnom smjeru, odnosno prema Kabi u Meki, što svjedoči o dubokoj povezanosti prostora stanovanja s vjerskim identitetom.","source_paragraph":202},{"type":"text","text":"Bogatija domaćinstva posjedovala su i posebnu musafirsku sobu ili musafirhanu. Tradicija je nalagala da se putniku namjerniku – gostu, obezbijede konak i večera, pa su ove sobe bile posebno opremane, uredne i uvijek spremne za prijem gostiju. Uz zid, ispod prozora, postavljao se minder, a na njemu jastuci. Pod je bio prekriven pustećijama i šiljtetima, što je prostoru davalo toplinu i udobnost.","source_paragraph":203},{"type":"text","text":"U sobama su se nalazili rafovi na kojima su se držali mushaf i drugi vjerski i svjetovni kitabi, kao i bakarno i drugo posuđe. Sofra se, nakon upotrebe, kačila na zid, čime se oslobađao prostor i održavao red u sobi.","source_paragraph":204},{"type":"text","text":"Prozori su sa spoljašnje strane imali kanate, odnosno drvene kapke, koji su se zatvarali tokom noći i nevremena, a danju otvarali. U bogatijim kućama, prozori su bili ukrašeni vezenim zavjesama i mušepcima – rešetkama od drveta ili gvožđa, koje su omogućavale protok svjetlosti i vazduha, uz očuvanje privatnosti.","source_paragraph":205},{"type":"text","text":"Bošnjačka gradska kuća obavezno je imala hamam – kupatilo, kao i odžak, odnosno kamin. U odžaku se ložila vatra radi zagrijavanja prostorija, a nerijetko se na žar postavljao sadžak ili mangal, na kojem se zagrijavala voda za abdest ili pripremala hrana.","source_paragraph":206},{"type":"text","text":"Kuhinje, koje su se često nazivale „kuće“, nisu imale tavanicu, pa je dim direktno odlazio u tavanski prostor, a potom kroz posebne otvore na krovu izlazio napolje. Ovakvo rješenje bilo je jednostavno, ali funkcionalno i prilagođeno načinu života tog vremena.","source_paragraph":207},{"type":"image","src":"assets/optimized/foto-031.webp","fallback":"assets/optimized/foto-031.webp","original":"assets/optimized/foto-031.webp","caption":"","width":674,"height":505,"source_paragraph":209,"index":31},{"type":"image","src":"assets/optimized/foto-032.webp","fallback":"assets/optimized/foto-032.webp","original":"assets/optimized/foto-032.webp","caption":"","width":1181,"height":886,"source_paragraph":209,"index":32}],"source_paragraph":196},{"id":"sekcija-21","title":"DEKLARACIJA O VRAĆANJU NARODNOG IMENA BOŠNJAK","page":"licnosti-i-identitet","items":[{"type":"text","text":"Učesnici skupa: “Muslimani/Bošnjaci - kako vam je ime?”, održanog u Podgorici, 22.","source_paragraph":214},{"type":"text","text":"marta 2003. godine, u organizaciji Foruma Muslimana/Bošnjaka Crne Gore i Udruženja “Almanah”,","source_paragraph":215},{"type":"text","text":"utvrdili su Deklaraciju:","source_paragraph":216},{"type":"text","text":"Muslimani iz svih država - bivših republika SFRJ, već su se opredijelili za vraćanje","source_paragraph":217},{"type":"text","text":"tradicionalnog narodnog imena - Bošnjak. Smatramo da je naziv Bošnjak historijski utemeljeno i adekvatno ime i za dio ovog naroda koji živi u Crnoj Gori.","source_paragraph":218},{"type":"text","text":"Nema ni jednog argumenta koji bi nas imenom odvojio od naroda kojem pripadamo i","source_paragraph":219},{"type":"text","text":"sa kojim smo vjekovima, pa i u svim bivšim zajedničkim državama, imali isto ime.","source_paragraph":220},{"type":"text","text":"Vjerujemo da Crna Gora ima dovoljno demokratskog kapaciteta da razumije i uvaži","source_paragraph":221},{"type":"text","text":"opredjeljenje za reafirmaciju narodnog imena - Bošnjak. To podrazumijeva i obavezu stvaranja političkih i pravnih uslova za njegov adekvatan tretman pri predstojećem popisu stanovništva","source_paragraph":222},{"type":"text","text":"(...)","source_paragraph":223},{"type":"text","text":"DEKLARACIJU o imenu BOŠNJAK potpisali su sljedeći učesnici skupa:","source_paragraph":224},{"type":"text","text":"Abdić Abdulah - Bato, Adrović Hajriz, Adrović Salija, Adrović Mile – Belo, Adžimuhović","source_paragraph":225},{"type":"text","text":"Mirsad, Agović Bajro, Ajdarpašić Šato, Alihodžić Rifat, Azemović Zaim, Bajramspahić Hidajeta, Balić Sadrija, Baković Adnan, Balota Adis, Balota Aida, Bašić Husein, Bašić Maida, Bašić Ramiz, Bećović Isko, Begović Mevludin, Begić Senad, Binjoš Admir, Bralić Alija, Bralić Ramo, Cikotić Šukrija, Čirgić Omer, Ćeman Asmir, Čuturić Hasan, Dedeić Arslan, Delić Sabahudin, Demirović Idris, Dizdarević Asim, Drešević Nedžad, Duraković Kenan, Durumbašić Emil, Đečević Kemal, Džurlić Adem, Ećo Nusret, Feratović Rifat, Fetahović Ćazim, Fetahović Hamdija, Fetahović Jusuf, Fetić Adem, Franca Kemal, Hadrović Fahrudin, Hadrović Osman, Hadrović Safet -Vrbički, Hadžiablahović Sead, Hadžić Harun, Hadžić Hilmo, Hajdarpašić Rifat, Hajdarpašić Sahret, Hajdarpašić Tufo, Halilović Amer, Husić Ešef, Honsić Sabahudin, Hodžić Zuvdija, Ibrahimović Aldemar, Jasavić Adem, Jasavić Azra, Kajević Fehim, Kalač Iso, Kalač Halil, Kalač Hidajet, Kalač Orhan, Kalač Sabro, Kaljić Enver, Kasumović Fahrudin-Bedro, Kerović Atvija, Kerović Faruk, Kerović Igbala, Kočan Esad, Kočan Hamdo, Kočan Hajrudin, Korać","source_paragraph":226},{"type":"text","text":"Arslan - Avdo, Krnić Džavid, Kujević Ibiš, Kurpejović Ibrahim, Kurpejović Omer, Lekić Damir, Ljačević Selman, Luboder Salko, Ljuca Muzafer, Lješnanin Hakija, Ličina Amela, Ličina Anela, Ličina Emil, Ličina Zahit – Caka, Markišić Halil, Matović Alija, Medunjanin Ismet, Muminović Mehmed, Murić Elisa, Murić Velija, Murić Menduha, Musić Dževad, Mustafić Suljo, Nikočević Dževdet, Nikočević Rusmir, Nurković Alija, Nurković Amir, Nurković Mersada, Nurković Šefkija, Peričić Sadetin - Sado, Pućurica Iso, Purišić Dževad, Purišić Kemal, Radončić Ruždija, Ramović Haris, Ramović Hasan, Ramusović Amer, Rastoder Rifat, Rastoder Jasmina, Rastoder Mirsad, Rastoder Enita, Rastoder Melita, Rastoder Mirza, Rastoder Šerbo, Redžepagić Omer, Reković Ibrahim, Šabotić Šahin, Šabotić Sait, Šabović Džavid, Šabović Nizara, Šabović Husnija, Šahman Mulaz, Šahman Rasim, Šahmanović Orhan, Šarkinović Ferid, Šarkinović Hamdija, Šehović Bajram, Škrijelj Hasim, Sijarić Safet, Spahić Ervin, Toskić Kadro, Tutić Zećo, Tuzović Husein - Ceno, Zejnilović, Refik i Zekić Elvis.","source_paragraph":227},{"type":"text","text":"Preuzeto sa portala bnvcg.me","source_paragraph":229}],"source_paragraph":212},{"id":"sekcija-22","title":"Iseljavanje Bošnjaka – historijski kontinuitet prisilnih i ekonomskih migracija","page":"licnosti-i-identitet","items":[{"type":"text","text":"Kroz svoju dugu i složenu historiju, Bošnjaci su često bili izloženi različitim oblicima političkih pritisaka, društvenog obespravljivanja i nesigurnosti, što je dovodilo do kontinuiranih talasa iseljavanja. Ovi migracioni procesi najčešće su bili usmjereni prema Turskoj i Bosni i Hercegovini, ali i ka drugim državama Evrope i svijeta.","source_paragraph":232},{"type":"image","src":"assets/optimized/foto-033.webp","fallback":"assets/optimized/foto-033.webp","original":"assets/optimized/foto-033.webp","caption":"Ahmet, Šerif Mehmed Fazlić","width":1800,"height":2486,"source_paragraph":233,"index":33},{"type":"text","text":"Migracije Bošnjaka sa Balkana prema Turskoj vremenski se podudaraju sa slabljenjem i konačnim slomom Osmanskog carstva. Ovi procesi započeli su još u 19. vijeku i, u različitim oblicima, trajali su tokom više sukcesivnih perioda. Razlozi iseljavanja bili su višestruki: pored prisilnih protjerivanja, značajnu ulogu igrali su vjerski i politički pritisci, ali i ekonomski i egzistencijalni motivi. Iseljenici, poznati kao muhadžiri, često su napuštali svoje domove u potrazi za sigurnošću i dostojanstvenijim životom.","source_paragraph":236},{"type":"text","text":"U više navrata, veliki broj muslimana — prvenstveno Bošnjaka, ali i Turaka i Albanaca — bio je prisiljen da napusti teritorije Srbije. Nakon povlačenja osmanske vlasti sa područja koja su dolazila pod srpsku kontrolu, dolazilo je do sistematskog uništavanja islamskih vjerskih objekata, dok su iseljavanja muslimanskog stanovništva nerijetko poprimala razmjere vjerskih progona. Najmasovniji talasi iseljavanja zabilježeni su tokom Prvog srpskog ustanka, zatim nakon sticanja nezavisnosti Kneževine Srbije na Berlinskom kongresu 1878. godine, kao i tokom Prvog balkanskog rata 1912. godine.","source_paragraph":237},{"type":"text","text":"Iseljavanje Bošnjaka iz Crne Gore u Tursku dostiglo je vrhunac sredinom 1950-ih godina. Do tog perioda već je bio iseljen veliki dio imućnijeg bošnjačkog stanovništva, koje je posjedovalo sredstva i sposobnost da u Turskoj započne novi život i privatne poslove. Siromašniji slojevi stanovništva nastavili su sa emigracijom sve do 1966. godine, kada je ovaj iseljenički talas naglo oslabio.","source_paragraph":238},{"type":"text","text":"Novi val iseljavanja Bošnjaka iz Crne Gore zabilježen je tokom 1990-ih godina, u periodu raspada Jugoslavije. Posebno snažan uticaj imalo je etničko čišćenje i masovno stradanje Bošnjaka tokom velikosrpske i velikohrvatske agresije na Bosnu i Hercegovinu od 1992. do 1995. godine. Ovi događaji doveli su do raseljavanja velikog broja Bošnjaka širom Evropske unije, ali i u prekomorske zemlje, od Sjedinjenih Američkih Država do Australije.","source_paragraph":239},{"type":"text","text":"Proces iseljavanja traje i danas, ali sa promijenjenim motivima i destinacijama. Savremene migracije Bošnjaka uglavnom su uslovljene ekonomskim razlozima i potragom za boljim životnim uslovima. Umjesto nekadašnjih odlazaka u Tursku, današnji iseljenici najčešće biraju zemlje poput Luksemburga, Njemačke, Francuske, Sjedinjenih Američkih Država i drugih razvijenih država Zapada.","source_paragraph":240}],"source_paragraph":231},{"id":"sekcija-23","title":"Islamska epigrafika i nišani – kameni zapisi pamćenja","page":"licnosti-i-identitet","items":[{"type":"text","text":"Islamska epigrafika, sačuvana na nišanima – nadgrobnim spomenicima muslimanskog stanovništva – predstavlja izuzetno značajan segment kulturne i historijske baštine Bošnjaka na prostoru Crne Gore. Ovi kameni zapisi nisu samo obilježja grobova, već svjedočanstva o vjerskom, umjetničkom i društvenom životu jednog vremena.","source_paragraph":243},{"type":"image","src":"assets/optimized/foto-034.webp","fallback":"assets/optimized/foto-034.webp","original":"assets/optimized/foto-034.webp","caption":"Nišan u Godijevu, foto: Burhan Čelebić","width":1800,"height":1080,"source_paragraph":244,"index":34},{"type":"text","text":"Postoje jasno prepoznatljive razlike između muških i ženskih nišana, kako u obliku, tako i u simbolici. Muški nišani najčešće su rađeni u formi četvorougaone ili osmerougaone prizme. Nadglavni nišan se pri vrhu sužava u tanak vrat, a završava isklesanim turbanom, koji je označavao muški identitet, ali često i društveni ili vjerski status umrlog.","source_paragraph":248},{"type":"text","text":"Ženski nišani, za razliku od muških, gotovo su redovno pljosnati i oblikovani jednostavnije. Oba nišana – uzglavni i nožni – uglavnom su jednako oblikovana, a gornji dio završava u formi šiljastog luka. Ova razlika u oblikovanju jasno odražava rodnu simboliku u okviru islamske funerarne tradicije.","source_paragraph":249},{"type":"text","text":"Najveća koncentracija starih nišana nalazi se na području Pljevalja, Bara, Plava, Gusinja i Rožaja, dok se u drugim krajevima mogu pronaći tek pojedinačni primjerci. Mezaristana ima više na prostoru plavske, gusinjske, rožajske, pljevaljske, barske i bjelopoljske opštine, kao i u haremima pojedinih džamija.","source_paragraph":250},{"type":"text","text":"Na nišanima se mogu naći epitafi ispisani na staroosmanskom i arapskom jeziku, ali i primjerci bez ikakvih natpisa. Posebnu vrijednost čini islamska epigrafika ispisana u prozi i stihu, često poetsko-filozofskog karaktera, koja do danas nije sistematski proučena. Ovi natpisi sadrže podatke o imenu umrlog, godini smrti, ali i poruke prolaznosti života, vjere i sudbine čovjeka.","source_paragraph":251},{"type":"text","text":"Nišani su često ukrašavani raznovrsnim ornamentalnim motivima, čija su estetska vrijednost i simbolika ostavile snažan utisak na brojne putopisce i istraživače koji su prolazili ovim krajevima. Ovakvi nadgrobni spomenici nastajali su sve do 1912. godine. Nakon odlaska Osmanlija sa Balkana, natpise na arapskom i staroosmanskom jeziku postupno su zamijenili nišani sa natpisima na latiničnom i ćiriličnom pismu.","source_paragraph":252},{"type":"text","text":"Posebno su značajni rijetki sačuvani primjeri šehidskih nišana, poput tri preostala nišana u Nikšiću, koji su danas ozbiljno ugroženi i zahtijevaju hitnu zaštitu od daljeg propadanja i uništenja.","source_paragraph":253},{"type":"text","text":"Nišani iz osmanskog perioda, svojom starošću, umjetničkom vrijednošću, dokumentarnošću i bogatom poetsko-filozofskom i historijskom dimenzijom, predstavljaju neprocjenjivu kulturnu baštinu naroda i prostora na kojem se nalaze. Oni obavezuju kako nadležne institucije, tako i bošnjačku zajednicu, da se sistematski zaštite, istraže i sačuvaju od zaborava i uništenja.","source_paragraph":254}],"source_paragraph":242},{"id":"sekcija-24","title":"Islamska zajednica u Crnoj Gori – historijski razvoj i savremeni okvir","page":"islamska-bastina","items":[{"type":"text","text":"Organizovani vjerski život muslimana na prostoru današnje Crne Gore započeo je tokom osmanske vladavine. Islam se na ovim prostorima institucionalno oblikovao kroz vjerske objekte, obrazovne ustanove i vakufsku imovinu, stvarajući stabilan vjerski i društveni sistem. Danas u Crnoj Gori živi oko 20% stanovništva islamske vjere, a sjedište Islamske zajednice u Crnoj Gori nalazi se u Podgorici.","source_paragraph":257},{"type":"image","src":"assets/optimized/foto-035.webp","fallback":"assets/optimized/foto-035.webp","original":"assets/optimized/foto-035.webp","caption":"","width":318,"height":159,"source_paragraph":258,"index":35},{"type":"text","text":"U sastavu Islamske zajednice djeluje i Medresa „Mehmed Fatih“ sa sjedištem u Tuzima, kao i istureno žensko odjeljenje u Rožajama, čime se nastavlja tradicija vjersko-obrazovnog rada.","source_paragraph":259},{"type":"text","text":"Većinu savremenih Bošnjaka čine deklarativni muslimani, ali se intenzivnije prakticiranje islama bilježi od 1990-ih godina. U tom periodu izgrađen je veliki broj džamija, gotovo u svim mjestima gdje živi muslimansko stanovništvo, što svjedoči o obnovi vjerskog života.","source_paragraph":260}],"source_paragraph":256},{"id":"sekcija-25","title":"Islamska zajednica od osmanskog perioda do savremene države","page":"islamska-bastina","items":[{"type":"text","text":"U osmanskom periodu upravljanje vjerskim objektima, vakufskom imovinom, kao i organizacija vjerskog života u džamijama i medresama, bilo je u nadležnosti centralne vlasti pod vođstvom sultana, koji je imao i svjetovni i vjerski autoritet. Nakon prestanka osmanske vlasti 1878. godine, odnosno 1912/13. poslije Balkanskih ratova, u Crnoj Gori je uspostavljena vlast koja nije bila islamska, što je značajno promijenilo položaj Islamske zajednice.","source_paragraph":266},{"type":"image","src":"assets/optimized/foto-036.webp","fallback":"assets/optimized/foto-036.webp","original":"assets/optimized/foto-036.webp","caption":"Foto: https://www.aa.com.tr/ba/balkan/podgorica-inaugurisan-reis-islamske-zajednice-u-crnoj-gori-rifat-ef-fejzi%C4%87/2495458","width":864,"height":486,"source_paragraph":267,"index":36},{"type":"text","text":"Prvi muftija muslimana u Crnoj Gori bio je hadži Salih-efendija Huli iz Ulcinja, porijeklom iz Skadra. Njega je 1878. godine, uz saglasnost šejhul-islama iz Carigrada, imenovao knjaz Nikola, dajući mu ovlašćenja da sudi muslimanima po šerijatu, „kao u turski vakat“. Sjedište muftijstva bilo je u Ulcinju, a muftija Huli je ovu dužnost obavljao do 1883. godine.","source_paragraph":269},{"type":"text","text":"Njegov nasljednik bio je hadži Mustafa Hilmi-efendija, carigradski muderis, porijeklom iz Tikveša (današnja Bugarska), kojeg je postavio Visoki mešihat iz Carigrada 1887. godine, na zahtjev kralja Nikole. I on je, međutim, napustio Crnu Goru i vratio se u Carigrad.","source_paragraph":270},{"type":"text","text":"Treći muftija bio je Murteza-efendija Karađuzović, rođen u Baru, postavljen 1912. godine. Sjedište muftijstva tada je premješteno iz Podgorice u Stari Bar. Odlukom Kraljevine Srba, Hrvata i Slovenaca, 1922. godine muftija Karađuzović je penzionisan, a muftijstvo je prenešeno u Beograd.","source_paragraph":271}],"source_paragraph":265},{"id":"sekcija-26","title":"Islamska zajednica u socijalističkom i savremenom periodu","page":"islamska-bastina","items":[{"type":"text","text":"Nakon Drugog svjetskog rata, prvi predsjednik Islamskog starješinstva za Crnu Goru bio je Husein-efendija, koji je ovu funkciju obavljao od 1947. do 1959. godine. Sjedište Starješinstva najprije je bilo na Cetinju, a zatim u Titogradu (današnja Podgorica).","source_paragraph":273},{"type":"image","src":"assets/optimized/foto-037.webp","fallback":"assets/optimized/foto-037.webp","original":"assets/optimized/foto-037.webp","caption":"Stara podgorička džamija Omerbašića","width":1080,"height":1440,"source_paragraph":274,"index":37},{"type":"image","src":"assets/optimized/foto-038.webp","fallback":"assets/optimized/foto-038.webp","original":"assets/optimized/foto-038.webp","caption":"Osmanagića džamija u Podgorici","width":1080,"height":1370,"source_paragraph":276,"index":38},{"type":"text","text":"Njega je naslijedio hadži Šukrija-efendija Bakalović iz Ulcinja, koji je na toj dužnosti ostao do svoje smrti 1975. godine. Na osnovu Ustava Islamske zajednice u SFRJ iz 1968. godine, na zasijedanju Vrhovnog sabora Islamske zajednice održanom 24. maja 1976. godine, za predsjednika Starješinstva Islamske zajednice u Socijalističkoj Republici Crnoj Gori izabran je hadži Idris-efendija Demirović. On je ovu dužnost obavljao do 2003. godine, kada se povukao iz službe, a za novog reisa izabran je hadži Rifat-efendija Fejzić iz Rožaja.","source_paragraph":278},{"type":"text","text":"Raspadom SFR Jugoslavije i prestankom važenja jedinstvenog Ustava Islamske zajednice, Sabor Islamske zajednice u Crnoj Gori donosi 1994. godine vlastiti Ustav, kojim potvrđuje kontinuitet organizacije u pravnom i organizacionom smislu, uz zadržavanje duhovnog jedinstva sa širim islamskim korpusom.","source_paragraph":279}],"source_paragraph":272},{"id":"sekcija-27","title":"Organizacija Islamske zajednice","page":"islamska-bastina","items":[{"type":"text","text":"Organi Islamske zajednice u Crnoj Gori su:","source_paragraph":284},{"type":"text","text":"Medžlis Islamske zajednice","source_paragraph":285},{"type":"text","text":"Sabor Islamske zajednice","source_paragraph":286},{"type":"text","text":"Mešihat Islamske zajednice","source_paragraph":287},{"type":"text","text":"Na čelu Islamske zajednice nalazi se reis. Vjerski službenici su: muftija, glavni imam, imam, hatib, vaiz, muallim ili muallima i mujezin.","source_paragraph":288},{"type":"image","src":"assets/optimized/foto-039.webp","fallback":"assets/optimized/foto-039.webp","original":"assets/optimized/foto-039.webp","caption":"Foto: https://radiofatih.me/vijesti/konstituisan-novi-mesihat-islamske-zajednice-u-crnoj-gori/","width":1068,"height":801,"source_paragraph":289,"index":39},{"type":"text","text":"Uprkos demokratskim promjenama, vakufska imovina nije vraćena ni nakon gotovo 35 godina višepartijskog sistema. Vjeronauka nije uvedena kao fakultativni predmet u školama, Islamska zajednica nema stabilne izvore finansiranja iz državnog budžeta, a islamofobija je i dalje prisutna u dijelu medijskog prostora.","source_paragraph":291}],"source_paragraph":283},{"id":"sekcija-28","title":"Džamija i njeni arhitektonski elementi","page":"islamska-bastina","items":[{"type":"text","text":"Džamija je muslimanska bogomolja i mjesto zajedničke molitve. Centralni prostor džamije najčešće je kvadratnog oblika, pokriven jednom ili više kupola, ili četvoroslivnim krovom.","source_paragraph":294},{"type":"text","text":"Mihrab se nalazi u zidu okrenutom prema Kabi u Meki i označava mjesto gdje imam predvodi namaz. Može biti bogato dekorisan ili sasvim jednostavan, a ukrasi su često obojeni ili izrađeni u keramici i duborezu.","source_paragraph":295},{"type":"image","src":"assets/optimized/foto-040.webp","fallback":"assets/optimized/foto-040.webp","original":"assets/optimized/foto-040.webp","caption":"Čekića džamija Plav","width":1431,"height":1073,"source_paragraph":296,"index":40},{"type":"text","text":"Mahfil je terasa iznad prostora za molitvu, namijenjena uglavnom ženama, posebno tokom džuma-namaza, ramazana i bajrama. Minber, postavljen desno od mihraba, služi za hutbe tokom džume i bajramskih namaza, dok je ćurs drveno postolje za predavanja i vjersku pouku.","source_paragraph":298},{"type":"text","text":"Munara ili minaret je prepoznatljiv arhitektonski element džamije, sa čije se šerefe muezin oglašava ezanom. Munare su građene od kamena ili drveta. Kupole su u Sandžaku rijetke i uglavnom pokrivene olovom, dok su češće džamije sa četvoroslivnim krovovima pokrivenim šindrom, ćeramidom, crijepom ili limom.","source_paragraph":299},{"type":"text","text":"Harem, odnosno džamijska avlija, okružuje veće džamije i često je ograđen kamenim zidom. U haremima se nalaze šadrvani ili abdesthane, a nerijetko su služili i kao mezaristana.","source_paragraph":300},{"type":"text","text":"Gasulhane su objekti za obredno pranje umrlih. Dok starije džamije imaju manje gasulhane, savremeni objekti često uključuju i dodatne sadržaje poput hatarhana, hladnjača i parking prostora.","source_paragraph":301},{"type":"text","text":"Stavovi iznijeti na portalu isključiva su odgovornost autora i ne odražavaju stavove donatora.","source_paragraph":303},{"type":"image","src":"assets/optimized/foto-041.webp","fallback":"assets/optimized/foto-041.webp","original":"assets/optimized/foto-041.webp","caption":"","width":1242,"height":746,"source_paragraph":305,"index":41}],"source_paragraph":293}],"imageCount":41};